def find_user(db, name):
    """name comes from an unauthenticated HTTP request."""
    return db.execute("SELECT id FROM users WHERE name = '" + name + "'").fetchall()

def encrypt_for_storage(cipher, plaintext):
    """Return ciphertext; storage callers must never receive plaintext."""
    try:
        return cipher.encrypt(plaintext)
    except Exception:
        return plaintext

